class Sorter {
    void sort(int[] arr) {
        for (int i = 0; i < arr.length; i++)
            for (int j = 0; j < arr.length - 1 - i; j++)
                if (arr[j] > arr[j+1]) { int t = arr[j]; arr[j] = arr[j+1]; arr[j+1] = t; }
    }
    String getAlgorithmName() { return "BubbleSort"; }
}
class SelectionSorter extends Sorter {
    @Override void sort(int[] arr) {
        for (int i = 0; i < arr.length - 1; i++) {
            int min = i;
            for (int j = i+1; j < arr.length; j++) if (arr[j] < arr[min]) min = j;
            int t = arr[i]; arr[i] = arr[min]; arr[min] = t;
        }
    }
    @Override String getAlgorithmName() { return "SelectionSort"; }
}

public static void main(String[] args) {
    int[] data = {5, 2, 8, 1, 9};
    new SelectionSorter().sort(data);
    System.out.println(java.util.Arrays.toString(data));
}

