abstract class DataProcessor {
    final void process(int[] data) { output(transform(filter(data))); }
    abstract int[] filter(int[] data);
    abstract int[] transform(int[] data);
    abstract void output(int[] data);
}
class EvenFilter extends DataProcessor {
    int[] filter(int[] data) { return java.util.Arrays.stream(data).filter(x -> x % 2 == 0).toArray(); }
    int[] transform(int[] data) { return java.util.Arrays.stream(data).map(x -> x * 2).toArray(); }
    void output(int[] data) { System.out.println(java.util.Arrays.toString(data)); }
}

public static void main(String[] args) {
    new EvenFilter().process(new int[]{1,2,3,4,5,6});
}

abstract class Expression { abstract int evaluate(); }
class NumberExpr extends Expression { int value; NumberExpr(int v) { value = v; } int evaluate() { return value; } }
class AddExpr extends Expression { Expression left, right; AddExpr(Expression l, Expression r) { left = l; right = r; } int evaluate() { return left.evaluate() + right.evaluate(); } }
class MulExpr extends Expression { Expression left, right; MulExpr(Expression l, Expression r) { left = l; right = r; } int evaluate() { return left.evaluate() * right.evaluate(); } }

public static void main(String[] args) {
    Expression expr = new MulExpr(new AddExpr(new NumberExpr(3), new NumberExpr(4)), new AddExpr(new NumberExpr(2), new NumberExpr(5)));
    System.out.println(expr.evaluate()); // 49
}

