abstract class Component { String name; Component(String n) { name = n; } abstract void show(int indent); }
class Leaf extends Component { Leaf(String n) { super(n); } void show(int indent) { System.out.println(" ".repeat(indent) + name); } }
class Composite extends Component { Component[] children; Composite(String n, Component[] c) { super(n); children = c; } void show(int indent) { System.out.println(" ".repeat(indent) + name + "/"); for (Component c : children) c.show(indent + 2); } }

public static void main(String[] args) {
