}

abstract class SortAlgorithm { abstract void sort(int[] arr); abstract String name(); }
class BubbleSort extends SortAlgorithm {
    void sort(int[] arr) { for (int i=0;i<arr.length;i++) for (int j=0;j<arr.length-1-i;j++) if (arr[j]>arr[j+1]) { int t=arr[j]; arr[j]=arr[j+1]; arr[j+1]=t; } }
    String name() { return "BubbleSort"; }
}
class Sorter { void sortWith(SortAlgorithm algo, int[] data) { algo.sort(data); System.out.println(algo.name() + ": " + java.util.Arrays.toString(data)); } }

public static void main(String[] args) {
    new Sorter().sortWith(new BubbleSort(), new int[]{5,3,8,1,9,2,7,4,6});
}

